import random,heapq

def sol(n,edges,x):
 g=[[]for _ in range(n)];r=[[]for _ in range(n)]
 for a,b in edges:g[a].append(b);r[b].append(a)
 d=[[10**9]*n for _ in range(2)];d[0][0]=0;h=[(0,0,0)]
 while h:
  z,s,v=heapq.heappop(h)
  if z!=d[s][v]:continue
  if v==n-1:return z
  for u in (g if s==0 else r)[v]:
   if z+1<d[s][u]:d[s][u]=z+1;heapq.heappush(h,(z+1,s,u))
  if z+x<d[1-s][v]:d[1-s][v]=z+x;heapq.heappush(h,(z+x,1-s,v))
for n in range(2,9):
 for q in range(500):
  es=[(a,b) for a in range(n) for b in range(n) if random.random()<.2]
  x=random.randint(1,8)
  # guarantee via add path
  for a in range(n-1):
   if (a,a+1) not in es: es.append((a,a+1))
  assert sol(n,es,x)>=0
