import sys
MOD=998244353

def solve(data):
    it=iter(map(int,data.split()))
    n=next(it); A=[next(it) for _ in range(n-1)]
    fac={}
    for i,x in enumerate(A):
        d=2
        while d*d<=x:
            if x%d==0:
                c=0
                while x%d==0: x//=d; c+=1
                fac.setdefault(d,[0]*(n-1))[i]=c
            d+=1
        if x>1: fac.setdefault(x,[0]*(n-1))[i]=1
    ans=1
    for p,aa in fac.items():
        H=sum(aa)
        dp=[0]*(H+1); dp[0]=1
        ph=[1]*(H+1)
        for j in range(1,H+1): ph[j]=ph[j-1]*p%MOD
        for i,a in enumerate(aa,1):
            if a==0:
                for h,v in enumerate(dp):
                    dp[h]=v*ph[h]%MOD
                continue
            nd=[0]*(H+1)
            base=pow(p,i,MOD)
            pr=[1]*(H+1)
            for j in range(1,H+1): pr[j]=pr[j-1]*base%MOD
            for de in (a,-a):
                for h,v in enumerate(dp):
                    if v:
                        z=h+de
                        if z>=0:
                            nd[z]=(nd[z]+v*ph[z])%MOD
                        else:
                            nd[0]=(nd[0]+v*pr[-z])%MOD
            dp=nd
        ans=ans*sum(dp)%MOD
    return str(ans)

sys.stdout.write(solve(sys.stdin.buffer.read()))

