import sys

MOD = 998244353

def main():
    z = list(map(int, sys.stdin.buffer.read().split()))
    if not z:
        return
    n = z[0]
    a = z[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for j in range(p, mx + 1, p):
                phi[j] -= phi[j] // p

    spf = list(range(mx + 1))
    for p in range(2, int(mx ** 0.5) + 1):
        if spf[p] == p:
            for j in range(p * p, mx + 1, p):
                if spf[j] == j:
                    spf[j] = p

    sums = [0] * (mx + 1)
    divcache = {}
    answer = 0
    weight = 1
    out = []

    for x in a:
        ds = divcache.get(x)
        if ds is None:
            ds = [1]
            y = x
            while y > 1:
                p = spf[y]
                power = 1
                while y % p == 0:
                    y //= p
                    power *= p
                old = ds[:]
                mul = 1
                while mul < power:
                    mul *= p
                    ds.extend(d * mul for d in old)
            ds = tuple(ds)
            divcache[x] = ds

        contribution = 0
        # The query and insertion are deliberately combined into one pass.
        for d in ds:
            old = sums[d]
            contribution += phi[d] * old
            new = old + weight
            sums[d] = new if new < MOD else new - MOD
        answer = (answer * 2 + contribution) % MOD
        out.append(str(answer))
        weight = (weight * 2) % MOD

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

