def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    # Smallest-prime-factor sieve.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, limit + 1, p):
                if spf[v] == v:
                    spf[v] = p

    nimber = 0
    for value in values:
        factors = 0
        while value > 1:
            value //= spf[value]
            factors += 1
        nimber ^= factors

    print("Anna" if nimber else "Bruno")


