class Solution:
    def maxSubarrays(self, n: int, conflictingPairs):
        # Group pairs by their larger endpoint.  For a fixed right endpoint,
        # only the largest smaller endpoint among already reached pairs matters.
        ending = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for idx, (x, y) in enumerate(conflictingPairs):
            if x > y:
                x, y = y, x
            ending[y].append((x, idx))

        largest = 0
        second = 0
        largest_id = -1
        gain = [0] * m
        base = 0

        for right in range(1, n + 1):
            for left_endpoint, idx in ending[right]:
                if left_endpoint > largest:
                    second = largest
                    largest = left_endpoint
                    largest_id = idx
                elif left_endpoint > second:
                    second = left_endpoint

            # Number of valid subarrays ending at right with all pairs present.
            base += right - largest
            # Removing the currently dominant pair relaxes the lower bound
            # from largest to second.
            if largest_id != -1:
                gain[largest_id] += largest - second

        return base + max(gain)

