    def maxSubarrays(self, n, conflictingPairs):
        ends = [[] for _ in range(n+1)]
        m = len(conflictingPairs)
        for i, (x,y) in enumerate(conflictingPairs):
            a,b = (x,y) if x<y else (y,x)
            ends[b].append((a,i))
        v1=v2=0; id1=-1
        gain=[0]*m
        base=0
        for r in range(1,n+1):
            for a,i in ends[r]:
                if a>v1:
                    v2=v1
                    v1=a; id1=i
                elif a>v2:
                    v2=a
            base += r-v1
            if id1>=0:
                gain[id1] += v1-v2
        return base+max(gain)

