import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it)-1, next(it)-1, next(it)))
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            k = next(it) - 1
            queries.append((1, k))
            closed[k] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**30
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for k, (a, b, w) in enumerate(edges):
        if not closed[k]:
            d[a][b] = d[b][a] = w

    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            x = di[k]
            for j in range(n):
                z = x + dk[j]
                if z < di[j]:
                    di[j] = z

    result = []
    for query in reversed(queries):
        if query[0] == 2:
            x = d[query[1]][query[2]]
            result.append(str(x if x < inf else -1))
        else:
            a, b, w = edges[query[1]]
            ra = d[a][:]
            rb = d[b][:]
            ca = [d[i][a] for i in range(n)]
            cb = [d[i][b] for i in range(n)]
            for i in range(n):
                di = d[i]
                xa = ca[i] + w
                xb = cb[i] + w
                for j in range(n):
                    v = di[j]
                    z = xa + rb[j]
                    if z < v:
                        v = z
                    z = xb + ra[j]
                    if z < v:
                        v = z
                    di[j] = v
    sys.stdout.write("\n".join(reversed(result)))

if __name__ == "__main__":
    main()

