        if qR>m:add(qL,qR,val,node*2+1,m+1,r)
        tree[node]=lazy[node]+max(tree[node*2],tree[node*2+1])
    def point(pos,val,node,l,r):
        if l==r: tree[node]=val; lazy[node]=0; return
        m=(l+r)//2
        if pos<=m:point(pos,val,node*2,l,m)
        else:point(pos,val,node*2+1,m+1,r)
        tree[node]=lazy[node]+max(tree[node*2],tree[node*2+1])
