    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = []
    upper = 10**30
    for i in range(n):
        a, p, b, q = data[2 + 4*i: 6 + 4*i]
        machines.append((a, p, b, q))
        # Even if all money is spent on the better of the two machine types,
        # this is an upper bound for the capacity at this process.
        upper = min(upper, max(budget * a // p, budget * b // q))

    def minimum_cost(target, a, p, b, q):
        best = 10**30
        # An optimum exists with either fewer than B S-machines or
        # fewer than A T-machines: otherwise remove B S and A T machines.
        for s in range(b):
            t = max(0, (target - s * a + b - 1) // b)
            value = s * p + t * q
            if value < best:
                best = value
        for t in range(a):
            s = max(0, (target - t * b + a - 1) // a)
            value = s * p + t * q
            if value < best:
                best = value
        return best

    def feasible(target):
        spent = 0
        for a, p, b, q in machines:
            spent += minimum_cost(target, a, p, b, q)
            if spent > budget:
                return False
        return True

    low = 0
    high = upper
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid - 1
    print(low)


if __name__ == '__main__':
    main()

