    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1
        for i in range(n):
            nd = [0] * (x + 1)
            for k in range(1, min(x, i + 1) + 1):
                nd[k] = (dp[k] * k + dp[k-1] * (x-k+1)) % MOD
            dp = nd
        ans = 0
        p = 1
        for k in range(1, min(x,n)+1):
            p = p*y % MOD
            ans = (ans + dp[k]*p) % MOD
        return ans

