class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # Binomial coefficients needed for choosing the remaining one-bits.
        choose = [[0] * (length + 1) for _ in range(length + 1)]
        choose[0][0] = 1
        for i in range(1, length + 1):
            choose[i][0] = choose[i][i] = 1
            for j in range(1, i):
                choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

        # If a number has m set bits, it is k-reducible exactly when m
        # reaches 1 in at most k-1 further applications.
        good = [False] * (length + 1)
        for m in range(1, length + 1):
            value = m
            operations = 0
            while value != 1:
                value = value.bit_count()
                operations += 1
            good[m] = operations <= k - 1

        # Count strings strictly below s, grouped by their number of ones.
        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for total in range(1, length + 1):
                    needed = total - used
                    if good[total] and 0 <= needed <= remaining:
                        answer = (answer + choose[remaining][needed]) % MOD
                used += 1

        return answer

