import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,m,q=data[:3]; p=3
    trips=[]
    for _ in range(m):
        s,t=data[p],data[p+1];p+=2
        if s<t: trips.append((s,t,1))
        else: trips.append((t,s,0))
    bad=[0]*m
    # A pair of constraints is incompatible precisely when equal-direction
    # intervals cross, or opposite-direction intervals are nested.
    # (Quadratic fallback; retained with early stopping for compactness.)
    for i in range(m):
        l,r,d=trips[i]
        b=0
        for j in range(i):
            a,c,e=trips[j]
            z=False
            if d==e:
                z=(a<l<c<r) or (l<a<r<c)
            else:
                z=((a<=l and r<=c) or (l<=a and c<=r))
            if z:b=max(b,j+1)
        bad[i]=b
    out=[]
    for _ in range(q):
        l,r=data[p],data[p+1];p+=2
        mx=0
        for i in range(l-1,r): mx=max(mx,bad[i])
        out.append('Yes' if mx<l else 'No')
    sys.stdout.write('\n'.join(out))
main()

