import sys, heapq

def main():
    input = sys.stdin.readline
    n = int(input())
    g = [input().strip() for _ in range(n)]
    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    INF = 10**9
    dist = [INF] * (n * n)
    row_max = [0] * n
    unresolved = [n] * n
    heap = []

    def put(state, value):
        if value < dist[state]:
            if dist[state] == INF:
                unresolved[state // n] -= 1
            dist[state] = value
            r = state // n
            if value > row_max[r]:
                row_max[r] = value
            heapq.heappush(heap, (value, state))

    for i in range(n):
        put(i * n + i, 0)
        for j, c in enumerate(g[i]):
            if c != '-':
                k = ord(c) - 97
                out[i][k].append(j)
                inc[j][k].append(i)
                put(i * n + j, 1)

    while heap:
        d, state = heapq.heappop(heap)
        if dist[state] != d:
            continue
        x, y = divmod(state, n)
        nd = d + 2
        for k in range(26):
            predecessors = inc[x][k]
            successors = out[y][k]
            if not predecessors or not successors:
                continue
            for u in predecessors:
                if unresolved[u] == 0 and row_max[u] <= nd:
                    continue
                base = u * n
                for v in successors:
                    target = base + v
                    if nd < dist[target]:
                        put(target, nd)

    for i in range(n):
        print(*(-1 if x == INF else x for x in dist[i*n:(i+1)*n]))

if __name__ == '__main__':
    main()

