import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[0::2]
    d = vals[1::2]

    upper = min(a + b for a, b in zip(u, d))
    U, D, X, N = u, d, x, n

    def feasible(h):
        lo = h - D[0]
        if lo < 0:
            lo = 0
        r = U[0]
        if lo > r:
            return False
        for i in range(1, N):
            z = h - D[i]
            if z < 0:
                z = 0
            q = lo - X
            if q > z:
                z = q
            q = r + X
            if q > U[i]:
                q = U[i]
            if z > q:
                return False
            lo = z
            r = q
        return True

    low = 0
    high = upper
    while low < high:
        mid = (low + high + 1) // 2
        if feasible(mid):
            low = mid
