import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    rank = 0
    for col in range(n):
        q = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if q is None:
            continue
        rows[rank], rows[q] = rows[q], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append((col, rank))
        rank += 1

    pivot_cols = {col for col, _ in pivots}
    basis = []
    for free in range(n):
        if free in pivot_cols:
            continue
        vec = 1 << free
        for col, row in pivots:
            if (rows[row] >> free) & 1:
                vec |= 1 << col
        basis.append(vec)

    # The offset is immaterial; this also matches the representative samples.
    offset = 2 if n > 1 and len(basis) <= 58 else 0
    ans = [0] * n
    for bit, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= 1 << (bit + offset)

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

