from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        N = n * m
        ds = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        # T[d][p] is the longest unturned sequence at a cell expecting
        # 2 (p=0) or 0 (p=1).
        T = [[array('H', [0]) * N for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(ds):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    for p in (0, 1):
                        if grid[r][c] == (2 if p == 0 else 0):
                            x, y = r + dr, c + dc
                            T[d][p][i] = 1 + (T[d][1-p][x*m+y]
                                if 0 <= x < n and 0 <= y < m else 0)
        ans = 0
        for d, (dr, dc) in enumerate(ds):
            V = [array('H', [0]) * N for _ in range(2)]
            nd = (d + 1) % 4
            tr, tc = ds[nd]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    i = r * m + c
                    val = grid[r][c]
                    for p in (0, 1):
                        if val == (2 if p == 0 else 0):
                            x, y = r + dr, c + dc
                            z = V[1-p][x*m+y] if 0 <= x < n and 0 <= y < m else 0
                            x, y = r + tr, c + tc
                            if 0 <= x < n and 0 <= y < m:
                                z = max(z, T[nd][1-p][x*m+y])
                            V[p][i] = 1 + z
                    if val == 1:
                        x, y = r + dr, c + dc
                        ans = max(ans, 1 + (V[0][x*m+y] if 0 <= x < n and 0 <= y < m else 0))
        return ans

