from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(CAP, factorial[i - 1] * i)

        def count(o: int, e: int, required: int | None) -> int:
            if required is None:
                if abs(o - e) > 1:
                    return 0
                patterns = 2 if o == e and o > 0 else 1
                return min(CAP, factorial[o] * factorial[e] * patterns)
            if required == 1:
                if not (o == e or o == e + 1):
                    return 0
            else:
                if not (e == o or e == o + 1):
                    return 0
            return min(CAP, factorial[o] * factorial[e])

        odd = (n + 1) // 2
        even = n // 2
        if k > count(odd, even, None):
            return []

        unused = [True] * (n + 1)
        result = []
        required = None
        o, e = odd, even

        for position in range(n):
            for value in range(1, n + 1):
                if not unused[value]:
                    continue
                if required is not None and value % 2 != required:
                    continue

                no = o - (value % 2)
                ne = e - (1 - value % 2)
                next_required = 1 - (value % 2)
                ways = (count(no, ne, next_required)
                        if position < n - 1 else 1)

                if ways == 0:
                    continue
                if k > ways:
                    k -= ways
                else:
                    result.append(value)
                    unused[value] = False
                    o, e = no, ne
                    required = next_required
                    break

        return result

