class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half_len = (n + 1) // 2

        # p[i] is 10**i modulo k.  The digit at half-position i
        # contributes with coefficient p[i] + p[n-1-i] (or just p[i]
        # for the middle digit).
        p = [0] * n
        p[0] = 1 % k
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k

        weights = [0] * half_len
        for i in range(half_len):
            if i == n - 1 - i:
                weights[i] = p[i]
            else:
                weights[i] = (p[i] + p[n - 1 - i]) % k

        # A mask represents the residues obtainable by a suffix of the
        # half.  Precompute adding an arbitrary decimal digit for every
        # mask and coefficient.
        transitions = [[0] * k for _ in range(1 << k)]
        for mask in range(1 << k):
            for weight in range(k):
                result = 0
                for residue in range(k):
                    if (mask >> residue) & 1:
                        for digit in range(10):
                            result |= 1 << ((residue + digit * weight) % k)
                transitions[mask][weight] = result

        suffix = [0] * (half_len + 1)
        suffix[half_len] = 1  # only residue zero for an empty suffix
        for i in range(half_len - 1, -1, -1):
            suffix[i] = transitions[suffix[i + 1]][weights[i]]

        digits = []
        residue = 0
        for i in range(half_len):
            for digit in range(9, -1, -1):
                if i == 0 and digit == 0:
                    continue
                new_residue = (residue + digit * weights[i]) % k
                needed = (-new_residue) % k
                if (suffix[i + 1] >> needed) & 1:
                    digits.append(str(digit))
                    residue = new_residue
                    break

        first_half = ''.join(digits)
        if n % 2:
            return first_half + first_half[:-1][::-1]
        return first_half + first_half[::-1]

