import sys

MOD = 998244353

def solve_case(H, W, grid):
    # p_i is the leftmost horizontal-edge bit of row i;
    # q_j is the topmost vertical-edge bit of column j.
    parent = list(range(H + W))
    xor_to_parent = [0] * (H + W)
    col_prefix = [0] * W

    def find(x):
        if parent[x] == x:
            return x, 0
        p = parent[x]
        root, value = find(p)
        xor_to_parent[x] ^= value
        parent[x] = root
        return root, xor_to_parent[x]

    for i, row in enumerate(grid):
        row_prefix = 0
        for j, ch in enumerate(row):
            if ch == 'B':
                u, xu = find(i)
                v, xv = find(H + j)
                # p_i xor q_j = 1 xor prefixes before this cell
                required = 1 ^ row_prefix ^ col_prefix[j]
                if u == v:
                    if (xu ^ xv) != required:
                        return 0
                else:
                    parent[u] = v
                    xor_to_parent[u] = xu ^ xv ^ required
            else:
                row_prefix ^= 1
                col_prefix[j] ^= 1
        if row_prefix:
            return 0

    if any(col_prefix):
        return 0
    components = sum(parent[x] == x for x in range(H + W))
    return pow(2, components, MOD)


def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    answers = []
    for _ in range(t):
        h = int(data[pos]); w = int(data[pos + 1]); pos += 2
        grid = [data[pos + i].decode() for i in range(h)]
        pos += h
        answers.append(str(solve_case(h, w, grid)))
    sys.stdout.write('\n'.join(answers))

if __name__ == '__main__':
    main()

