class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            m = len(t)
            mark = [False] * (n + 1)
            if m == 0:
                return mark
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    mark[i - m + 1] = True
                    j = pi[j - 1]
            return mark

        def next_occurrence(mark, is_empty):
            if is_empty:
                return list(range(n + 1))
            result = [n + 1] * (n + 1)
            latest = n + 1
            for i in range(n, -1, -1):
                if mark[i]:
                    latest = i
                result[i] = latest
            return result

        ma = occurrences(a)
        mb = occurrences(b)
        mc = occurrences(c)
        next_b = next_occurrence(mb, not b)
        next_c = next_occurrence(mc, not c)

        best = n + 1
        if a:
            starts = (i for i in range(n - len(a) + 1) if ma[i])
        else:
            starts = range(n + 1)
        for start in starts:
            b_start = next_b[start + len(a)]
            if b_start > n:
                continue
            c_start = next_c[b_start + len(b)]
            if c_start <= n:
                best = min(best, c_start + len(c) - start)
        return -1 if best == n + 1 else best

