    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    potential = [0] * n
    visited = [False] * n
    answer = [0] * n

    for start in range(n):
        if visited[start]:
            continue
        visited[start] = True
        stack = [start]
        component = []
        while stack:
            u = stack.pop()
            component.append(u)
            for v, z in graph[u]:
                expected = potential[u] ^ z
                if not visited[v]:
                    visited[v] = True
                    potential[v] = expected
                    stack.append(v)
                elif potential[v] != expected:
                    print(-1)
                    return

        size = len(component)
        ones = [0] * 30
        for u in component:
            value = potential[u]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1
        shift = 0
        for bit in range(30):
            if ones[bit] * 2 > size:
                shift |= 1 << bit
        for u in component:
            answer[u] = potential[u] ^ shift

    print(*answer)

