from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Construct the postorder iteratively.  Children are pushed/visited
        # in their natural increasing order.
        post = []
        stack = [(0, 0)]
        while stack:
            v, next_child = stack[-1]
            if next_child < len(children[v]):
                u = children[v][next_child]
                stack[-1] = (v, next_child + 1)
                stack.append((u, 0))
            else:
                post.append(v)
                stack.pop()

        position = [0] * n
        for i, v in enumerate(post):
            position[v] = i

        subtree_size = [1] * n
        for v in post:
            if v != 0:
                subtree_size[parent[v]] += subtree_size[v]

        text = ''.join(s[v] for v in post)

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes; center is before i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = []
        for v in range(n):
            r = position[v]
            l = r - subtree_size[v] + 1
            length = subtree_size[v]
            if length & 1:
                center = (l + r) // 2
                answer.append(odd[center] >= length // 2 + 1)
            else:
                center = (l + r + 1) // 2
                answer.append(even[center] >= length // 2)
        return answer

