class Solution:
    def countPairs(self, nums: List[int]) -> int:
        cache = {}

        def variants(x: int):
            if x not in cache:
                s = list(str(x))
                values = {x}
                for i in range(len(s)):
                    for j in range(i + 1, len(s)):
                        t = s[:]
                        t[i], t[j] = t[j], t[i]
                        # Converting to int correctly handles leading zeroes.
                        values.add(int(''.join(t)))
                cache[x] = values
            return cache[x]

        answer = 0
        for i, y in enumerate(nums):
            possible_from_y = variants(y)
            for x in nums[:i]:
                if x in possible_from_y or y in variants(x):
                    answer += 1
        return answer

