class Solution:
    def countPairs(self, nums: List[int]) -> int:
        cache = {}

        def variants(x: int):
            if x not in cache:
                s = list(str(x))
                values = {x}
                for i in range(len(s)):
                    for j in range(i + 1, len(s)):
                        t = s[:]
                        t[i], t[j] = t[j], t[i]
                        # Converting to int correctly handles leading zeroes.
