from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # A line (m, b) represents dp[i] + nums[i] * (x-i).
        # Thus its value at x is m*x+b.
        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(line, node, left, right):
            current = tree[node]
            if current is None:
                tree[node] = line
                return
            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                tree[node], line = line, current
            if left == right:
                return
            if value(line, left) > value(tree[node], left):
                add(line, node * 2, left, mid)
            elif value(line, right) > value(tree[node], right):
                add(line, node * 2 + 1, mid + 1, right)

        def best(x, node, left, right):
            line = tree[node]
            result = value(line, x) if line is not None else -10**30
            if left == right:
                return result
            mid = (left + right) // 2
            if x <= mid:
                return max(result, best(x, node * 2, left, mid))
            return max(result, best(x, node * 2 + 1, mid + 1, right))

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for j in range(1, n):
            answer = best(j, 1, 0, n - 1)
            add((nums[j], answer - j * nums[j]), 1, 0, n - 1)
        return answer

