import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits - 1

        is_prime = bytearray(b'\1') * (limit + 1)
        is_prime[0:2] = b'\0\0'
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                is_prime[p * p:limit + 1:p] = b'\0' * (((limit - p * p) // p) + 1)

        if is_prime[n] or is_prime[m]:
            return -1

        places = [10 ** i for i in range(digits)]
        infinity = 10 ** 30
        distances = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distances[value]:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    new_cost = cost + nxt
                    if not is_prime[nxt] and new_cost < distances.get(nxt, infinity):
                        distances[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    new_cost = cost + nxt
                    if not is_prime[nxt] and new_cost < distances.get(nxt, infinity):
                        distances[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))

        return -1

