from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        inf = m + 1
        # dp[j] is the minimum number of target characters needed by a
        # matching subsequence for pattern[:j].
        dp = [inf] * (m + 1)
        dp[0] = 0

        is_target = bytearray(len(source))
        for index in targetIndices:
            is_target[index] = 1

        for i, ch in enumerate(source):
            cost = is_target[i]
            # Descending order ensures that this source character is used
            # at most once.
            for j in range(m - 1, -1, -1):
                if ch == pattern[j]:
                    value = dp[j] + cost
                    if value < dp[j + 1]:
                        dp[j + 1] = value

        return len(targetIndices) - dp[m]

