class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        reverse = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.append(w)

        values = sorted(set(weights))

        def possible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if not seen[u] and w <= limit:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        if not values or not possible(values[-1]):
            return -1

        lo, hi = 0, len(values) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if possible(values[mid]):
                hi = mid
            else:
                lo = mid + 1
        return values[lo]

