from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30
        dp = [[INF] * 3 for _ in range(3)]

        # Choose colors for the first pair: positions 0 and n-1.
        for left in range(3):
            for right in range(3):
                if left != right:
                    dp[left][right] = cost[0][left] + cost[n - 1][right]

        # Add successive pairs moving toward the center.
        for i in range(1, n // 2):
            ndp = [[INF] * 3 for _ in range(3)]
            left_cost = cost[i]
            right_cost = cost[n - 1 - i]
            for left in range(3):
                for right in range(3):
                    if left == right:
                        continue
                    best_previous = min(
                        dp[old_left][old_right]
                        for old_left in range(3)
                        for old_right in range(3)
                        if old_left != left and old_right != right
                    )
                    ndp[left][right] = (
                        best_previous + left_cost[left] + right_cost[right]
                    )
            dp = ndp

        return min(min(row) for row in dp)

