class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'
        runs = []
        i = 0
        n = len(t)
        while i < n:
            j = i
            c = t[i]
            while j < n and t[j] == c:
                j += 1
            runs.append((c, j-i))
            i = j
        best = 0
        for i in range(1, len(runs)-1):
            if runs[i][0] == '1':
                best = max(best, runs[i-1][1] + runs[i+1][1])
        return base + best

