class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        present = {(x, y) for x, y in points}
        answer = -1

        for i in range(len(points)):
            x1, y1 = points[i]
            for j in range(i + 1, len(points)):
                x2, y2 = points[j]
                # Use the selected pair as opposite corners.
                if x1 == x2 or y1 == y2:
                    continue
                left, right = sorted((x1, x2))
                bottom, top = sorted((y1, y2))
                corners = {
                    (left, bottom), (left, top),
                    (right, bottom), (right, top)
                }
                if not corners.issubset(present):
                    continue

                valid = True
                for x, y in points:
                    if (x, y) not in corners and left <= x <= right and bottom <= y <= top:
                        valid = False
                        break
                if valid:
                    answer = max(answer, (right - left) * (top - bottom))

        return answer

